        "µ": {"item": "ds-body", "props": {"host": true, "title": "Dr. Ruth Imber", "kicker": "Lab 3-B", "angle": 1.9, "color": "#e8ecee", "skin": "#f0d4b8", "hair": "#a8a8a8", "text": "Dr. Ruth Imber. Lab 3-B. They died early in the night, and they are lying very straight, as if somebody arranged them to be found. Or used."}},
