        "·": {"enemy": "ds-ridden", "props": {"coat": "#e8ecee", "skin": "#4a3020", "hair": "#0e0a08", "name": "Dr. Paul Okafor", "card": "clearance3", "cardFlag": "clearance3", "cardName": "Level 3 clearance card", "cardColor": "#58b2ff", "cardTitle": "Dr. Okafor’s card", "cardText": "LEVEL 3 · GESTATION\nDR. P. OKAFOR · HEAD OF NEURAL TENANCY\n\nIt’s warm from his pocket.", "cardDesc": "LEVEL 3 · GESTATION · P. OKAFOR. It opens Stair B."}, "tag": "okafor"},
        "¹": {"enemy": "ds-ridden", "props": {"coat": "#e8ecee", "skin": "#e0c0a0", "hair": "#5a3a1a", "name": "Dr. Hal Brenner"}},
