        "Ù": {"item": "ds-note", "props": {"title": "A framed photograph", "kicker": "Dr. Brandt’s office", "text": "Five people in evening dress on a terrace at night, glasses raised. Voss in the middle. Brandt beside him, laughing. Behind them, out of focus, a building on fire."}},
        "Ú": {"item": "ds-note", "props": {"sticky": true, "title": "A sticky note on the screen", "kicker": "Dr. Brandt’s office", "text": "She is not cruel.\nShe is careful.\n— I.B."}},
